PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), external_subject TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), organization_id TEXT REFERENCES organizations(id), title TEXT NOT NULL, target_repo TEXT NOT NULL, target_branch TEXT NOT NULL, custom_env_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS authenticated_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repositories (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), provider TEXT NOT NULL, full_name TEXT NOT NULL, UNIQUE(organization_id,provider,full_name));
CREATE TABLE IF NOT EXISTS repository_revisions (id TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id), commit_sha TEXT NOT NULL, branch TEXT NOT NULL, observed_at INTEGER NOT NULL, UNIQUE(repository_id,commit_sha));
CREATE TABLE IF NOT EXISTS missions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), organization_id TEXT NOT NULL REFERENCES organizations(id), specification_json TEXT NOT NULL, specification_checksum TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, mission_id TEXT REFERENCES missions(id), session_id TEXT REFERENCES sessions(id), user_id TEXT REFERENCES users(id), organization_id TEXT REFERENCES organizations(id), repository_revision_id TEXT REFERENCES repository_revisions(id), target_repo TEXT NOT NULL, target_branch TEXT NOT NULL, execution_mode TEXT NOT NULL, status TEXT NOT NULL, workflow_run_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, finished_at INTEGER, summary TEXT);
CREATE TABLE IF NOT EXISTS run_transitions (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), from_state TEXT NOT NULL, to_state TEXT NOT NULL, idempotency_key TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(run_id,idempotency_key));
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), plan_version INTEGER NOT NULL, packet_json TEXT NOT NULL, state TEXT NOT NULL, superseded_by TEXT REFERENCES tasks(id), lease_owner TEXT, lease_expires_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS task_dependencies (task_id TEXT NOT NULL REFERENCES tasks(id), depends_on_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_id));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), number INTEGER NOT NULL, base_commit TEXT NOT NULL, result_json TEXT, started_at INTEGER NOT NULL, finished_at INTEGER, UNIQUE(task_id,number));
CREATE TABLE IF NOT EXISTS checkpoints (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), task_id TEXT REFERENCES tasks(id), schema_version INTEGER NOT NULL, body_json TEXT NOT NULL, mission_checksum TEXT NOT NULL, repository_revision TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS memories (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), organization_id TEXT NOT NULL REFERENCES organizations(id), repository_id TEXT REFERENCES repositories(id), class TEXT NOT NULL, scope_json TEXT NOT NULL, provenance_json TEXT NOT NULL, source_run_id TEXT REFERENCES runs(id), source_revision TEXT, confidence REAL NOT NULL, body_json TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, invalidated_at INTEGER, created_at INTEGER NOT NULL, validated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS instruction_sources (id TEXT PRIMARY KEY, repository_revision_id TEXT REFERENCES repository_revisions(id), source_path TEXT NOT NULL, scope TEXT NOT NULL, precedence INTEGER NOT NULL, checksum TEXT NOT NULL, content_ref TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL, owner_id TEXT, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, UNIQUE(owner_type,owner_id,name));
CREATE TABLE IF NOT EXISTS skill_versions (id TEXT PRIMARY KEY, skill_id TEXT NOT NULL REFERENCES skills(id), version TEXT NOT NULL, manifest_json TEXT NOT NULL, trust_level TEXT NOT NULL, approved_at INTEGER, UNIQUE(skill_id,version));
CREATE TABLE IF NOT EXISTS connector_configs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL, encrypted_config BLOB NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), organization_id TEXT NOT NULL REFERENCES organizations(id), object_key TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, checksum TEXT NOT NULL, scan_status TEXT NOT NULL, expires_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS run_attachments (run_id TEXT NOT NULL REFERENCES runs(id), attachment_id TEXT NOT NULL REFERENCES attachments(id), PRIMARY KEY(run_id,attachment_id));
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), user_id TEXT NOT NULL REFERENCES users(id), capability TEXT NOT NULL, proposed_action_json TEXT NOT NULL, status TEXT NOT NULL, decided_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tool_calls (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), task_id TEXT REFERENCES tasks(id), capability TEXT NOT NULL, sanitized_arguments_json TEXT NOT NULL, sanitized_result_json TEXT, status TEXT NOT NULL, latency_ms INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_calls (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), task_id TEXT REFERENCES tasks(id), provider TEXT NOT NULL, model TEXT NOT NULL, operation TEXT NOT NULL, capability_snapshot_json TEXT NOT NULL, routing_reason TEXT NOT NULL, context_estimate INTEGER, usage_json TEXT, cost_usd REAL, latency_ms INTEGER, error TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS token_cost_ledger (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), provider_call_id TEXT NOT NULL REFERENCES provider_calls(id), input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, cost_usd REAL NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), task_id TEXT, attempt_id TEXT, agent_id TEXT NOT NULL, sequence INTEGER NOT NULL, timestamp INTEGER NOT NULL, type TEXT NOT NULL, schema_version INTEGER NOT NULL, payload_json TEXT NOT NULL, idempotency_key TEXT NOT NULL, UNIQUE(run_id,sequence), UNIQUE(run_id,idempotency_key));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), run_id TEXT REFERENCES runs(id), role TEXT NOT NULL, type TEXT NOT NULL, content TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', timestamp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS git_artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), kind TEXT NOT NULL, branch TEXT, commit_sha TEXT, pull_request_number INTEGER, workflow_correlation_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verification_evidence (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), task_id TEXT REFERENCES tasks(id), command TEXT NOT NULL, exit_code INTEGER NOT NULL, output_ref TEXT, workspace_mutation_at INTEGER, verified_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (scope TEXT NOT NULL, key TEXT NOT NULL, response_json TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(scope,key));
CREATE INDEX IF NOT EXISTS idx_events_replay ON events(run_id,sequence);
CREATE INDEX IF NOT EXISTS idx_tasks_run_state ON tasks(run_id,state);
CREATE INDEX IF NOT EXISTS idx_memories_scope ON memories(user_id,repository_id,class);
